appsmith.onReady(() => {
  renderForm();
  appsmith.onModelChange(model => {
    renderForm();
  });
});
function renderForm() {
  const container = document.getElementById('rows-container');
  if (!container) return;
  const userFiles = appsmith.model.userUploadedFiles || {};
  const rows = appsmith.model.documentRows || [{
    id: 'boq',
    title: 'BOQ / Scope',
    badge: 'Mandatory',
    badgeClass: 'bg-blue-50 text-blue-600 border-blue-100',
    description: 'PR attachments classified as BOQ or scope, plus the system-generated BOQ / scope file.',
    selectedFile: 'BOQ_Scope_BHS_Upgrade.xlsx',
    autoGenerated: true,
    autoGeneratedText: 'Selected: BOQ_Scope_BHS_Upgrade.xlsx',
    options: ['⭐ BOQ_Scope_BHS_Upgrade.xlsx...']
  }, {
    id: 'technical',
    title: 'Technical document',
    badge: 'Optional',
    badgeClass: 'bg-slate-100 text-slate-600 border-slate-200',
    description: 'PR attachments classified by AI as technical',
    hasCheckbox: true,
    checkboxLabel: 'I acknowledge this file contains sensitive references and confirm to attach it',
    selectedFile: 'Vendor_Budgetary_Quote_and_Scope.pdf',
    autoGenerated: true,
    autoGeneratedText: 'Selected: Vendor_Budgetary_Quote_and_Scope.pdf — Acknowledged (Estimated total budget / price reference of INR 12,50,000 detected.)',
    options: ['Vendor_Budgetary_Quote_and_Scope.pdf']
  }, {
    id: 'drawing',
    title: 'Drawing / datasheet',
    badge: 'Optional',
    badgeClass: 'bg-slate-100 text-slate-600 border-slate-200',
    description: 'PR attachments classified by AI as drawing or datasheet',
    selectedFile: '-- None / Exclude --',
    autoGenerated: false,
    options: ['-- None / Exclude --']
  }, {
    id: 'other',
    title: 'Other special terms',
    badge: 'Optional',
    badgeClass: 'bg-slate-100 text-slate-600 border-slate-200',
    description: 'Buyer-provided documents (not from PR)',
    selectedFile: '-- None / No special terms --',
    autoGenerated: false,
    options: ['-- None / No special terms --']
  }];
  container.innerHTML = rows.map(row => {
    let currentOptions = [...row.options];
    let selectedValue = row.selectedFile;

    // Check if a file was uploaded for this row and append it
    if (userFiles[row.id]) {
      const uploadedFileName = userFiles[row.id].name;
      if (!currentOptions.includes(uploadedFileName)) {
        currentOptions.unshift(uploadedFileName);
      }
      selectedValue = uploadedFileName;
    }
    return `
      <div class="border border-slate-200 rounded-xl p-4 bg-white flex items-center justify-between gap-4" data-row-id="${row.id}">
          <div class="w-[28%]">
              <div class="flex items-center gap-2">
                  <span class="font-semibold text-slate-800 text-sm">${row.title}</span>
                  <span class="${row.badgeClass} text-[11px] px-2 py-0.5 rounded-full font-medium border">${row.badge}</span>
              </div>
              <p class="text-xs text-slate-500 mt-1 leading-relaxed">${row.description}</p>
              ${row.hasCheckbox ? `
                  <label class="flex items-start gap-2 mt-2 text-xs text-slate-600 cursor-pointer">
                      <input type="checkbox" checked class="mt-0.5 rounded border-slate-300 text-blue-600 focus:ring-blue-500">
                      <span>${row.checkboxLabel}</span>
                  </label>
              ` : ''}
          </div>

          <div class="w-[22%]">
              <label class="block text-xs font-medium text-slate-500 mb-1">Select file ${row.badge === 'Optional' ? '(optional)' : ''}</label>
              <div class="relative">
                  <select class="w-full text-xs border border-slate-300 rounded-lg p-2.5 bg-white text-slate-700 appearance-none pr-8 focus:outline-none focus:ring-1 focus:ring-blue-500 file-select">
                      ${currentOptions.map(opt => `<option ${opt === selectedValue ? 'selected' : ''}>${opt}</option>`).join('')}
                  </select>
                  <span class="absolute right-3 top-3 text-xs text-slate-400 pointer-events-none">▼</span>
              </div>
          </div>

          <div class="w-[26%] ${row.autoGenerated ? 'bg-emerald-50/60 border border-emerald-200/80' : 'bg-slate-50 border border-slate-200'} rounded-lg p-2.5 text-xs">
              <span class="font-semibold ${row.autoGenerated ? 'text-emerald-800' : 'text-slate-600'} block text-[11px]">
                  ${row.autoGenerated ? 'Auto-Generated' : 'None'}
              </span>
              <span class="${row.autoGenerated ? 'text-emerald-700' : 'text-slate-500'} truncate block mt-0.5">
                  ${userFiles[row.id] ? 'Manually Uploaded: ' + userFiles[row.id].name : row.autoGeneratedText}
              </span>
          </div>

          <div class="w-[20%] border-2 border-dashed border-slate-200 rounded-lg p-3 text-center hover:bg-slate-50 cursor-pointer transition relative">
              <input type="file" class="absolute inset-0 opacity-0 cursor-pointer file-input" onchange="handleFileBrowse(event, '${row.id}')">
              <span class="text-xs text-slate-600 font-medium truncate block">${userFiles[row.id] ? userFiles[row.id].name : 'Drag & drop or browse'}</span>
          </div>
      </div>
    `;
  }).join('');
}
window.handleFileBrowse = function (event, rowId) {
  const file = event.target.files[0];
  if (file) {
    const existingFiles = appsmith.model.userUploadedFiles || {};
    existingFiles[rowId] = {
      name: file.name,
      size: file.size,
      type: file.type
    };
    appsmith.updateModel({
      userUploadedFiles: existingFiles
    });
  }
};
window.handleCancel = function () {
  appsmith.triggerEvent('onCancelClick');
};
window.handleSave = function () {
  const selections = {};
  document.querySelectorAll('[data-row-id]').forEach(rowEl => {
    const rowId = rowEl.getAttribute('data-row-id');
    const selectEl = rowEl.querySelector('.file-select');
    if (selectEl) {
      selections[rowId] = selectEl.value;
    }
  });
  appsmith.updateModel({
    formSelections: selections
  });
  appsmith.triggerEvent('onSaveClick');
};

